#!/usr/bin/env node
// Deterministic JS→Go conformance fixtures for updates whose struct section
// does not decode: an update cut short, or one with a malformed struct after
// a valid one.
//
// yjs reads every struct of an update (readClientsStructRefs) before it
// integrates any, so when a struct fails to decode the update changes
// nothing and no update event fires. Each row is a base update, an update
// (cut at every byte for the well-formed ones), and the state yjs reaches
// after applying both.
//
// Determinism: pinned clientIDs, canonical JSON, trailing newline.
// Regenerated by `make fixtures`; CI's drift gate diffs the result.
const Y = require('yjs')
const encoding = require('lib0/encoding')
const fs = require('fs')
const path = require('path')
const assert = require('assert')

const outDir = path.join(__dirname, '..', 'crdt', 'testdata')
const hex = (u8) => Buffer.from(u8).toString('hex')

// writer returns a doc where client 1 has written "abcdef" into the text t.
function writer () {
  const doc = new Y.Doc()
  doc.clientID = 1
  doc.getText('t').insert(0, 'abcdef')
  return doc
}
const base = writer()
const baseV1 = Y.encodeStateAsUpdate(base)
const baseV2 = Y.encodeStateAsUpdateV2(base)
const baseSV = Y.encodeStateVector(base)

// edit applies f to the text of a new writer and returns the V1 and V2
// updates of what f wrote.
function edit (f) {
  const doc = writer()
  f(doc.getText('t'))
  return [Y.encodeStateAsUpdate(doc, baseSV), Y.encodeStateAsUpdateV2(doc, baseSV)]
}

// build writes client groups with an empty delete set; by default one group
// of client 1's structs from clock 6. Each struct is a function that writes
// it to the encoder.
function build (Encoder, structs, groups = [{ client: 1, clock: 6, structs }]) {
  const enc = new Encoder()
  encoding.writeVarUint(enc.restEncoder, groups.length)
  for (const g of groups) {
    encoding.writeVarUint(enc.restEncoder, g.structs.length)
    enc.writeClient(g.client)
    encoding.writeVarUint(enc.restEncoder, g.clock)
    for (const s of g.structs) s(enc)
  }
  encoding.writeVarUint(enc.restEncoder, 0)
  return enc.toUint8Array()
}

const BIT8 = 0x80 // origin
const BIT7 = 0x40 // right origin
const between = (tag, left, right) => (enc) => {
  enc.writeInfo(BIT8 | BIT7 | tag)
  enc.writeLeftID(Y.createID(1, left))
  enc.writeRightID(Y.createID(1, right))
}
const x = (enc) => { between(4, 0, 1)(enc); enc.writeString('X') }
const structs = {
  // "X" between a and b, as Y.Text.insert(1, 'X') writes it.
  x,
  // a GC struct of length 1
  gc: (enc) => { enc.writeInfo(0); enc.writeLen(1) },
  // "X" whose origin is a client the document has never seen
  xAfterMissing: (enc) => {
    enc.writeInfo(BIT8 | BIT7 | 4)
    enc.writeLeftID(Y.createID(2, 0))
    enc.writeRightID(Y.createID(1, 1))
    enc.writeString('X')
  },
  // content tag 12, which no content type has
  badTag: between(12, 3, 4),
  // ContentJSON whose value is not JSON
  badJSON: (enc) => { between(2, 3, 4)(enc); enc.writeLen(1); enc.writeString('x') }
}

function outcome (fmt, update) {
  const doc = new Y.Doc()
  fmt === 'v1' ? Y.applyUpdate(doc, baseV1) : Y.applyUpdateV2(doc, baseV2)
  const events = []
  doc.on('update', (u) => events.push(hex(u)))
  let error = false
  try {
    fmt === 'v1' ? Y.applyUpdate(doc, update) : Y.applyUpdateV2(doc, update)
  } catch (e) {
    error = true
  }
  return {
    error,
    delta: doc.getText('t').toDelta(),
    sv: Object.fromEntries([...Y.decodeStateVector(Y.encodeStateVector(doc))].map(([c, k]) => [String(c), k])),
    pending: doc.store.pendingStructs !== null,
    events
  }
}

const rows = []
function add (name, v1, v2, { cuts }) {
  for (const [fmt, update, base] of [['v1', v1, baseV1], ['v2', v2, baseV2]]) {
    const ends = cuts ? [...Array(update.length + 1).keys()] : [update.length]
    for (const end of ends) {
      const cut = update.slice(0, end)
      rows.push({ name, fmt, cut: end, len: update.length, base: hex(base), update: hex(cut), expected: outcome(fmt, cut) })
    }
  }
}

// The well-formed updates come from yjs; build must write the same bytes, so
// the malformed ones differ from a real update only in the struct they break.
const [twoV1, twoV2] = edit((t) => { t.insert(1, 'X'); t.insert(5, 'Y') })
const y = (enc) => { between(4, 3, 4)(enc); enc.writeString('Y') }
assert.deepStrictEqual(build(Y.UpdateEncoderV1, [x, y]), twoV1)
assert.deepStrictEqual(build(Y.UpdateEncoderV2, [x, y]), twoV2)
add('two_strings', twoV1, twoV2, { cuts: true })

// V2 keeps an embed's JSON in its last column, so a cut there ends inside
// the second struct rather than inside the delete set.
const [embedV1, embedV2] = edit((t) => { t.insert(1, 'X'); t.insertEmbed(5, { k: 'vv' }) })
add('string_then_embed', embedV1, embedV2, { cuts: true })

for (const [name, list] of [
  ['bad_tag_after_string', [structs.x, structs.badTag]],
  ['bad_json_after_string', [structs.x, structs.badJSON]],
  ['bad_tag_after_gc', [structs.gc, structs.badTag]],
  ['bad_tag_after_parked', [structs.xAfterMissing, structs.badTag]]
]) {
  add(name, build(Y.UpdateEncoderV1, list), build(Y.UpdateEncoderV2, list), { cuts: false })
}

// Client 2 writes "X" between a and b; client 1's group after it is malformed.
for (const [name, bad] of [['bad_tag_in_later_group', structs.badTag], ['bad_json_in_later_group', structs.badJSON]]) {
  const groups = [{ client: 2, clock: 0, structs: [structs.x] }, { client: 1, clock: 6, structs: [bad] }]
  add(name, build(Y.UpdateEncoderV1, null, groups), build(Y.UpdateEncoderV2, null, groups), { cuts: false })
}

for (const r of rows) {
  if (r.cut === r.len && !r.name.startsWith('bad_')) assert(!r.expected.error, `${r.name} ${r.fmt} applies whole`)
  if (r.name.startsWith('bad_')) assert(r.expected.error && r.expected.events.length === 0, `${r.name} ${r.fmt} changes nothing`)
}

const file = path.join(outDir, 'structdecode_yjs_fixtures.json')
fs.writeFileSync(file, JSON.stringify(rows, null, 2) + '\n')
console.log(`wrote crdt/testdata/structdecode_yjs_fixtures.json (${rows.length} rows)`)
